#nullable enable // autogenerated

using System;
using MVZ2.Blueprints;
using MVZ2.Level.UI;
using MVZ2.Models;
using MVZ2.UI;
using MVZ2Logic.Inputs;
using MVZ2Logic.Models;
using PVZEngine;
using TMPro;
using UnityEngine;
using UnityEngine.EventSystems;

namespace MVZ2.GameContent.Customize
{
    public class TeleporterTeamUI : MonoBehaviour
    {
        #region 蓝图
        public void SetBlueprintDisplayerPlatform(bool mobile)
        {
            standaloneBlueprintDisplayer.gameObject.SetActive(!mobile);
            mobileBlueprintDisplayer.gameObject.SetActive(mobile);
        }
        public void SetBlueprintEntries(bool mobile, ChoosingBlueprintViewData[] entries)
        {
            var displayer = mobile ? mobileBlueprintDisplayer : standaloneBlueprintDisplayer;
            displayer.SetBlueprintEntries(entries);
        }
        public void DisableBlueprintDisplayerScrollRectDragging()
        {
            mobileBlueprintDisplayer.DisableScrollRectDragging();
        }
        public void SetBlueprintSelected(bool mobile, int index, bool selected)
        {
            var displayer = mobile ? mobileBlueprintDisplayer : standaloneBlueprintDisplayer;
            displayer.SetBlueprintSelected(index, selected);
        }
        public Blueprint? GetBlueprintUI(bool mobile, int index)
        {
            var displayer = mobile ? mobileBlueprintDisplayer : standaloneBlueprintDisplayer;
            return displayer.GetBlueprint(index);
        }
        #endregion

        #region 能量
        public void SetEnergy(string energy)
        {
            energyLabel.text = energy;
        }
        #endregion

        #region 地块
        public void SetLayoutTileCount(int count)
        {
            layout.SetTileCount(count);
        }
        public void SetLayoutTileHighlight(int index, Color color)
        {
            layout.SetTileHighlight(index, color);
        }
        public void ClearTiles()
        {
            layout.ClearTiles();
        }
        public void AddTileEntity(int index, NamespaceID entityID, IModelBuilder modelBuilder, string? sortingLayer, int sortingOrder)
        {
            layout.AddTileEntity(index, entityID, modelBuilder, sortingLayer, sortingOrder);
        }
        public void RemoveTileEntity(int index, NamespaceID entityID)
        {
            layout.RemoveTileEntity(index, entityID);
        }
        #endregion

        #region 手持物
        public void SetHoldingModel(IModelBuilder modelBuilder)
        {
            holdingModelContainer.SetModel(modelBuilder);
        }
        public void SetHoldingModelPosition(Vector3 worldPosition)
        {
            holdingModelContainer.transform.position = worldPosition;
        }
        public void ClearHoldingModel()
        {
            holdingModelContainer.RemoveModel();
        }
        #endregion

        #region 铁镐
        public PickaxeSlot GetPickaxeSlot()
        {
            return pickaxe;
        }
        public void SetPickaxeSelected(bool selected)
        {
            pickaxe.SetSelected(selected);
        }
        #endregion
        private void Awake()
        {
            standaloneBlueprintDisplayer.OnBlueprintPointerInteraction += OnBlueprintPointerInteractionCallback;
            standaloneBlueprintDisplayer.OnConfirmClick += OnConfirmClickCallback;
            standaloneBlueprintDisplayer.OnCancelClick += OnCancelClickCallback;
            mobileBlueprintDisplayer.OnBlueprintPointerInteraction += OnBlueprintPointerInteractionCallback;
            mobileBlueprintDisplayer.OnConfirmClick += OnConfirmClickCallback;
            mobileBlueprintDisplayer.OnCancelClick += OnCancelClickCallback;

            pickaxe.OnPointerEnter += OnPickaxePointerEnterCallback;
            pickaxe.OnPointerExit += OnPickaxePointerExitCallback;
            pickaxe.OnPointerDown += OnPickaxePointerDownCallback;
            layout.OnPointerInteraction += OnLayoutTilePointerInteractionCallback;
        }
        private void OnBlueprintPointerInteractionCallback(int index, PointerEventData eventData, PointerInteraction interaction)
        {
            OnBlueprintPointerInteraction?.Invoke(index, eventData, interaction);
        }
        private void OnLayoutTilePointerInteractionCallback(int index, PointerEventData eventData, PointerInteraction interaction)
        {
            OnLayoutTilePointerInteraction?.Invoke(index, eventData, interaction);
        }
        private void OnPickaxePointerEnterCallback(PointerEventData eventData)
        {
            OnPickaxePointerEnter?.Invoke(eventData);
        }
        private void OnPickaxePointerExitCallback(PointerEventData eventData)
        {
            OnPickaxePointerExit?.Invoke(eventData);
        }
        private void OnPickaxePointerDownCallback(PointerEventData eventData)
        {
            OnPickaxePointerDown?.Invoke(eventData);
        }
        private void OnConfirmClickCallback()
        {
            OnConfirmClick?.Invoke();
        }
        private void OnCancelClickCallback()
        {
            OnCancelClick?.Invoke();
        }
        public event Action<int, PointerEventData, PointerInteraction>? OnBlueprintPointerInteraction;
        public event Action<int, PointerEventData, PointerInteraction>? OnLayoutTilePointerInteraction;
        public event Action<PointerEventData>? OnPickaxePointerEnter;
        public event Action<PointerEventData>? OnPickaxePointerExit;
        public event Action<PointerEventData>? OnPickaxePointerDown;
        public event Action? OnConfirmClick;
        public event Action? OnCancelClick;
        [SerializeField]
        private ModelContainer holdingModelContainer = null!;
        [SerializeField]
        private TextMeshProUGUI energyLabel = null!;
        [SerializeField]
        private TeleporterTeamBlueprintDisplayerUI standaloneBlueprintDisplayer = null!;
        [SerializeField]
        private TeleporterTeamBlueprintDisplayerUI mobileBlueprintDisplayer = null!;
        [SerializeField]
        private PickaxeSlot pickaxe = null!;
        [SerializeField]
        private TeleporterTeamLayoutUI layout = null!;
    }
}
